--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned NOT NULL,
  `brand_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `sku` varchar(255) NOT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`details`)),
  `base_price` decimal(15,2) NOT NULL,
  `compare_at_price` decimal(15,2) DEFAULT NULL,
  `discount_type` varchar(255) NOT NULL DEFAULT 'none',
  `discount_value` decimal(15,2) NOT NULL DEFAULT 0.00,
  `discount_start_at` timestamp NULL DEFAULT NULL,
  `discount_end_at` timestamp NULL DEFAULT NULL,
  `is_discount_active` tinyint(1) NOT NULL DEFAULT 0,
  `badge` varchar(255) DEFAULT NULL,
  `is_trending` tinyint(1) NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_new` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(255) NOT NULL DEFAULT 'active',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  KEY `products_is_trending_index` (`is_trending`),
  KEY `products_is_featured_index` (`is_featured`),
  KEY `products_is_new_index` (`is_new`),
  KEY `products_status_index` (`status`),
  KEY `fk_products_category` (`category_id`),
  KEY `fk_products_brand` (`brand_id`),
  CONSTRAINT `products_brand_id_foreign` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,1,1,'Stride AeroGlide Carbon','stride-aeroglide-carbon','STR-AGC-001','Marathon Racing Shoe','Engineered for sub-3-hour marathoners and elite road racers. Features our proprietary full-length curved carbon fiber propulsion plate suspended in dual-density nitrogen-infused BioFoam.','{\"Drop\":\"8mm\",\"Weight\":\"198g (US 9)\",\"Stack Height\":\"39mm heel \\/ 31mm forefoot\",\"Upper\":\"Single-layer engineered monomesh\",\"Midsole\":\"Supercritical BioFoam with carbon plate\"}',2100000.00,2100000.00,'fixed',32.00,NULL,NULL,1,'SALE',1,1,0,'active',NULL,'2026-10-15 00:03:14','2026-10-15 00:03:14'),(2,1,1,'Stride PaceMaker 3','stride-pacemaker-3','STR-PM3-002','High-Mileage Daily Trainer','The workhorse of your training block. Tested over 800+ kilometers of continuous abuse without foam pack-out. Cushioned, forgiving, yet delightfully energetic on toe-off.','{\"Drop\":\"10mm\",\"Weight\":\"245g (US 9)\",\"Stack Height\":\"34mm \\/ 24mm\",\"Outsole\":\"Full-contact blown rubber compound\"}',1450000.00,NULL,'none',0.00,NULL,NULL,0,'NEW',1,1,1,'active',NULL,'2026-10-15 00:03:14','2026-10-15 00:03:14'),(3,5,3,'TrailVenture Pro GTX','trailventure-pro-gtx','STR-TVP-003','Technical Alpine Trail Runner','Conquer wet scrambles, scree, and technical mountain singletracks. Outfitted with Gore-Tex Invisible Fit waterproof membrane and a directional 5mm Vibram Megagrip lug configuration.','{\"Drop\":\"6mm\",\"Weight\":\"285g (US 9)\",\"Lug Depth\":\"5.0mm multidirectional\",\"Waterproofing\":\"Gore-Tex Invisible Fit\"}',1890000.00,NULL,'none',0.00,NULL,NULL,0,'WATERPROOF',1,1,0,'active',NULL,'2026-10-15 00:03:14','2026-10-15 00:03:14'),(4,3,2,'CloudShift Recovery Slip','cloudshift-recovery-slip','STR-CSR-004','Post-Workout Active Recovery','Slip on blissful relief post-long run. Sculpted ergonomic footbed with anatomical arch support aligns your lower kinetic chain while the rocker sole encourages natural calf recovery.','{\"Arch Support\":\"Deep contour bio-foam\",\"Upper\":\"Breathable open-cell waffle mesh\",\"Care\":\"Machine washable cold cycle\"}',1200000.00,1200000.00,'fixed',25.00,NULL,NULL,1,'SALE',1,0,0,'active',NULL,'2026-10-15 00:03:14','2026-10-15 00:03:14'),(5,2,4,'UrbanStance Classic Low','urbanstance-classic-low','STR-USC-005','Heritage Everyday Sneaker','Timeless minimalist court silhouette handcrafted with supple Italian full-grain nappa leather and durable vulcanized natural gum soles. Built for all-day urban comfort.','{\"Leather\":\"Full-grain Italian calfskin\",\"Lining\":\"Smooth calf leather\",\"Sole\":\"Natural vulcanized gum rubber\"}',1350000.00,NULL,'none',0.00,NULL,NULL,0,'BEST SELLER',1,1,0,'active',NULL,'2026-10-15 00:03:15','2026-10-15 00:03:15'),(6,1,1,'CloudStrider Low','cloudstrider-low','STR-CSL-006','Featherweight Tempo Trainer','Precision balance of featherweight upper mesh and dynamic propulsion foam. Ideal for 5K workouts, tempo runs, and daily sprints.','{\"Drop\":\"6mm\",\"Weight\":\"210g\",\"Midsole\":\"BioFoam ActiveLite\"}',1400000.00,NULL,'none',0.00,NULL,NULL,0,NULL,0,1,1,'active',NULL,'2026-10-15 00:03:15','2026-10-15 00:03:15'),(7,5,3,'Terraform Runner','terraform-runner','STR-TFR-007','All-Terrain Adventure Runner','Engineered for smooth transitions between pavement and steep backcountry trails. Rock plate protection and ripstop upper.','{\"Drop\":\"5mm\",\"Weight\":\"260g\",\"Protection\":\"Ballistic woven rock shield\"}',1850000.00,NULL,'none',0.00,NULL,NULL,0,NULL,0,1,0,'active',NULL,'2026-10-15 00:03:15','2026-10-15 00:03:15'),(8,8,1,'Merino Wool Sock 3-Pack','merino-wool-sock-3-pack','STR-MWS-008','Anti-Blister Running Socks','Seamless toe construction crafted with 200-needle superfine Australian merino wool. Naturally moisture-wicking and odor-resistant.','{\"Material\":\"65% Merino Wool, 30% Recycled Nylon, 5% Lycra\",\"Cushion\":\"Targeted heel and forefoot micro-terry\"}',380000.00,NULL,'none',0.00,NULL,NULL,0,'BEST SELLER',0,1,0,'active',NULL,'2026-10-15 00:03:15','2026-10-15 00:03:15'),(9,1,1,'Velocity Glide Elite','velocity-glide-elite','STR-CAT-010','Engineered for Performance & Movement','Designed with thoughtful biomechanical parameters to support natural articulation and maximum energy return.','{\"Construction\":\"Stitchless heat-welded overlay\",\"Material\":\"100% Vegan & Recycled Components\"}',1950000.00,NULL,'none',0.00,NULL,NULL,0,'NEW',1,1,1,'active',NULL,'2026-10-15 00:03:16','2026-10-15 00:03:16'),(10,1,1,'Strata Road Master','strata-road-master','STR-CAT-011','Engineered for Performance & Movement','Designed with thoughtful biomechanical parameters to support natural articulation and maximum energy return.','{\"Construction\":\"Stitchless heat-welded overlay\",\"Material\":\"100% Vegan & Recycled Components\"}',1550000.00,NULL,'none',0.00,NULL,NULL,0,NULL,1,0,0,'active',NULL,'2026-10-15 00:03:16','2026-10-15 00:03:16'),(11,1,1,'AeroKnit Sprint 2','aeroknit-sprint-2','STR-CAT-012','Engineered for Performance & Movement','Designed with thoughtful biomechanical parameters to support natural articulation and maximum energy return.','{\"Construction\":\"Stitchless heat-welded overlay\",\"Material\":\"100% Vegan & Recycled Components\"}',1300000.00,1300000.00,'fixed',20.00,NULL,NULL,1,'SALE',0,0,0,'active',NULL,'2026-10-15 00:03:16','2026-10-15 00:03:16'),(12,1,1,'HyperBreeze 10K','hyperbreeze-10k','STR-CAT-013','Engineered for Performance & Movement','Designed with thoughtful biomechanical parameters to support natural articulation and maximum energy return.','{\"Construction\":\"Stitchless heat-welded overlay\",\"Material\":\"100% Vegan & Recycled Components\"}',1600000.00,NULL,'none',0.00,NULL,NULL,0,NULL,0,1,0,'active',NULL,'2026-10-15 00:03:16','2026-10-15 00:03:16'),(13,1,1,'Endurance Marathon Pro','endurance-marathon-pro','STR-CAT-014','Engineered for Performance & Movement','Designed with thoughtful biomechanical parameters to support natural articulation and maximum energy return.','{\"Constru