INSERT INTO `promotions` VALUES (1,'Spring Performance Sale — Up to 40% Off Select Running Models','Spring Sale Is Live!','Limited inventory on our carbon-plated racers and daily trainers. Engineered for long-distance durability. Ends midnight Sunday.','Up to 40% Off','/storage/banners/promo-runner.jpg','/storage/banners/promo-plate.jpg','Shop the Sale →','/shop?sale=1','2026-10-14 00:03:14','2026-10-20 16:59:59',1,'2026-10-15 00:03:14','2026-10-15 00:03:14');
