INSERT INTO `reviews` VALUES (1,1,3,NULL,5,'Game changer for my marathon block','The foam energy return is unbelievable. Ran 32km on Saturday and woke up with zero knee ache. Stride has truly nailed the propulsion geometry.',1,1,'2026-09-04 00:03:14','2026-10-15 00:03:14'),(2,1,4,NULL,5,'Best road shoe I have tested this year','Light, breathable, and locks down the midfoot securely. Fits true to size with an anatomical toe box.',1,1,'2026-09-05 00:03:14','2026-10-15 00:03:14'),(3,1,5,NULL,5,'Exceptional build quality','Zero break-in required right out of the box. The craftsmanship and attention to detail justify every single dollar.',1,1,'2026-06-22 00:03:14','2026-10-15 00:03:14'),(4,1,6,NULL,4,'Super comfortable daily trainer','Logged 250 miles so far and the outsole shows virtually no wear. Very impressed with the bio-foam durability.',1,1,'2026-08-26 00:03:14','2026-10-15 00:03:14'),(5,1,7,NULL,5,'Clean aesthetic and top-tier comfort','Transitioned from running straight to the cafe. Gorgeous styling and the cushioning is remarkably plush.',1,1,'2026-09-10 00:03:14','2026-10-15 00:03:14'),(6,1,8,NULL,5,'Snug heel lockdown','No heel slippage whatsoever. Breathability in warm weather is unmatched. Highly recommended.',1,1,'2026-07-27 00:03:14','2026-10-15 00:03:14'),(7,1,9,NULL,4,'Solid performance and great aesthetics','Slightly snug on the arch initially, but molded to my foot after two 5-mile runs. Fantastic traction in the wet.',1,1,'2026-06-28 00:03:14','2026-10-15 00:03:14'),(8,1,10,NULL,5,'Game changer for my marathon block','The foam energy return is unbelievable. Ran 32km on Saturday and woke up with zero knee ache. Stride has truly nailed the propulsion geometry.',1,1,'2026-10-10 00:03:14','2026-10-15 00:03:14'),(9,1,11,NULL,5,'Best road shoe I have tested this year','Light, breathable, and locks down the midfoot securely. Fits true to size with an anatomical toe box.',1,1,'2026-07-29 00:03:14','2026-10-15 00:03:14'),(10,1,12,NULL,5,'Exceptional build qua